out = {"note": "Hive Hunt lists, one a day in rotation from start. Membership only; answers never leave the server until a hunt is finished.", "start": "2026-11-20", "lists": []}
for i, l in enumerate(L):
    entries = []
    for e in l["entries"]:
        parts = []
        for p in e.split("|"):
            p = p.strip()
            if p and p not in parts: parts.append(p)
        entries.append(parts)
    out["lists"].append({"id": i + 1, "prompt": l["prompt"], "entries": entries, "unlisted": l["unlisted"], "source": l["source"]})
print(json.dumps(out, indent=1, ensure_ascii=False))
